import{_ as r,o,c as a,a2 as n}from"./chunks/framework.CRFziyHp.js";const s="/images/placeholder-health-center.svg",p=JSON.parse('{"title":"系统监控入口","description":"","frontmatter":{},"headers":[],"relativePath":"ops/monitoring.md","filePath":"ops/monitoring.md","lastUpdated":1785013113000}'),d={name:"ops/monitoring.md"};function e(l,t,i,g,h,c){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="系统监控入口" tabindex="-1">系统监控入口 <a class="header-anchor" href="#系统监控入口" aria-label="Permalink to &quot;系统监控入口&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>说明管理后台 <strong>系统监控</strong> 分组各菜单的用途，便于管理员日常巡检与问题定位。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>已登录管理后台 H5。</li><li>账号具备 <code>system.monitor:read</code> 或相应模块读权限（部分菜单需更高权限）。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><p>路径：侧栏 <strong>系统监控</strong>（无需额外「开启」，部署正常即可用）</p><table tabindex="0"><thead><tr><th>菜单</th><th>管理员何时使用</th></tr></thead><tbody><tr><td><strong>数据统计</strong></td><td>查看用户、内容、订单等运营概览</td></tr><tr><td><strong>系统状态</strong></td><td>每日巡检：数据库、Redis、支付回调、队列是否正常</td></tr><tr><td><strong>服务健康中心</strong></td><td>查看各依赖服务自愈状态与历史告警</td></tr><tr><td><strong>运行时指标</strong></td><td>内存、 Goroutine 等资源占用偏高时</td></tr><tr><td><strong>API 指标</strong></td><td>接口延迟、错误率突增时</td></tr><tr><td><strong>数据库性能</strong></td><td>慢查询、连接池紧张时</td></tr><tr><td><strong>定时任务</strong></td><td>确认同步、对账、Token 刷新等任务在跑</td></tr><tr><td><strong>搜索索引</strong></td><td>Meilisearch 同步与重建，见 <a href="/features/search">搜索与推荐</a></td></tr><tr><td><strong>相关推荐评估</strong></td><td>启用 Gorse 后查看推荐效果</td></tr><tr><td><strong>对账中心</strong></td><td>支付 / 资金异常对账</td></tr><tr><td><strong>链接巡检</strong></td><td>笔记外链失效批量检测</td></tr><tr><td><strong>联动中心</strong></td><td>跨模块联动任务状态</td></tr><tr><td><strong>导出任务</strong></td><td>异步导出 Excel 等任务进度</td></tr><tr><td><strong>系统动态</strong></td><td>健康巡检写入的告警时间线</td></tr><tr><td><strong>在线用户</strong></td><td>当前 WebSocket 在线规模</td></tr></tbody></table><p><img src="'+s+'" alt="服务健康中心示意"></p><h3 id="建议巡检节奏" tabindex="-1">建议巡检节奏 <a class="header-anchor" href="#建议巡检节奏" aria-label="Permalink to &quot;建议巡检节奏&quot;">​</a></h3><table tabindex="0"><thead><tr><th>频率</th><th>查看菜单</th></tr></thead><tbody><tr><td>每日</td><td><strong>系统状态</strong>、<strong>定时任务</strong></td></tr><tr><td>每周</td><td><strong>数据统计</strong>、<strong>搜索索引</strong></td></tr><tr><td>出问题时</td><td><strong>系统动态</strong> → <strong>API 指标</strong> / <strong>消息链路追踪</strong>（通知模块）</td></tr></tbody></table><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>监控数据 <strong>全站汇总</strong>；区域管理员若被授权，部分列表（如用户、内容）会按区域过滤，但 <strong>系统状态</strong> 仍为全站视角。</p><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>打开 <strong>系统监控 → 系统状态</strong>，各核心依赖显示绿色或「正常」。</li><li><strong>定时任务</strong> 列表最近执行时间在预期范围内（如微信 Token 刷新、搜索同步）。</li><li>故意断开 Redis（仅测试环境）后，<strong>系统动态</strong> 出现告警记录（生产勿试）。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>菜单缺失</strong></p><ul><li>账号权限不足；见 <a href="/ops/faq">常见问题</a>「403 / 菜单没有」。</li><li>部分菜单依赖可选模块（如 <strong>搜索索引</strong> 需搜索能力）。</li></ul><p><strong>看不懂指标</strong></p><ul><li>管理员优先看 <strong>系统状态</strong> 红字与 <strong>系统动态</strong> 文案；细粒度 Prometheus 由运维接入 Grafana。</li></ul><p><strong>与通知控制台的区别</strong></p><ul><li><strong>系统监控</strong>：基础设施与任务。</li><li><strong>通知控制台</strong>：业务通知模板与用户消息投递。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/search">搜索与推荐</a></li><li><a href="/ops/docker-infra">可选基础设施</a></li><li><a href="/ops/checklist">上线检查清单</a></li><li><a href="/ops/faq">常见问题</a></li></ul>',24)])])}const b=r(d,[["render",e]]);export{p as __pageData,b as default};
